harnessSources.harnessText:
// Evidence-only filesystem observation. All operations delegate unchanged.
const fs = require('node:fs');
const path = require('node:path');
const own = __dirname;
const log = process.env.SYZYGY_WAIT_TRACE;
if (!log || !log.startsWith(own + '/logs/')) throw Error('trace outside OWN');
const read = fs.readFileSync, write = fs.writeFileSync, remove = fs.rmSync, append = fs.appendFileSync;
const event = data => append(log, JSON.stringify({ pid: process.pid, ...data }) + '\n');
const outside = file => typeof file === 'string' && /^\/tmp\/dossier-signoff-[^/]+-outside-RAW\.md$/.test(file);
fs.writeFileSync = function(file, ...args) {
  const result = write.call(this, file, ...args);
  if (outside(file)) event({kind:'outside-written', file, bytes:read(file,'utf8')});
  return result;
};
fs.readFileSync = function(file, ...args) {
  const result = read.call(this, file, ...args);
  if (typeof file === 'string' && file.startsWith('/tmp/dossier-signoff-') && file.endsWith('/POLARIS-DOSSIER-LOCAL-AGENT-MODE-SIGNOFF-v1.2.md')) {
    const text = String(result), review = /^Review: (.+)$/m.exec(text)?.[1];
    if (review?.includes('..')) {
      const root = file.slice(0, file.indexOf('/.syzygy/'));
      const raw = path.join(root, review);
      event({kind:'record-read', file, root, review, raw, present:fs.existsSync(raw), record:text, stack:new Error().stack});
    }
  }
  return result;
};
fs.rmSync = function(file, ...args) {
  const tracked = outside(file), before = tracked && fs.existsSync(file);
  const result = remove.call(this, file, ...args);
  if (tracked) event({kind:'outside-removed', file, before, after:fs.existsSync(file), options:args[0]});
  return result;
};
